// Dark mode switch: follows the device until the visitor picks, then remembers the pick.
const THEME_KEY = "hello-theme";
const root = document.documentElement;
const themeBtn = document.getElementById("theme-toggle");
const darkQuery = window.matchMedia("(prefers-color-scheme: dark)");

function currentTheme() {
  const t = root.getAttribute("data-theme");
  if (t === "dark" || t === "light") return t;
  return darkQuery.matches ? "dark" : "light";
}
function syncThemeButton() {
  themeBtn.setAttribute("aria-checked", currentTheme() === "dark" ? "true" : "false");
}

let savedTheme = null;
try { savedTheme = localStorage.getItem(THEME_KEY); } catch (e) {}
if (savedTheme === "dark" || savedTheme === "light") root.setAttribute("data-theme", savedTheme);
syncThemeButton();

themeBtn.addEventListener("click", () => {
  const next = currentTheme() === "dark" ? "light" : "dark";
  root.setAttribute("data-theme", next);
  try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  syncThemeButton();
});
darkQuery.addEventListener("change", syncThemeButton);
new MutationObserver(syncThemeButton).observe(root, { attributes: true, attributeFilter: ["data-theme"] });

// Tap a greeting to swap the headline word; tap it again to go back to "Hello".

