/* Small hearts drifting up behind the page */
.hearts {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  overflow: hidden;
}
.heart {
  position: absolute;
  bottom: -2rem;
  left: var(--x);
  font-size: var(--size);
  line-height: 1;
  color: var(--accent);
  opacity: var(--o);
  animation: heart-float var(--dur) linear infinite;
  animation-delay: var(--delay);
}
.heart > span {
  display: inline-block;
  animation: heart-sway var(--sway) ease-in-out infinite alternate;
}
@keyframes heart-float {
  to { transform: translateY(calc(-100vh - 4rem)); }
}
@keyframes heart-sway {
  from { transform: translateX(-0.6em) rotate(-14deg); }
  to { transform: translateX(0.6em) rotate(14deg); }
}

